// CEP:WHAT: Sums bytes of one buffer.
// CEP:WHY: Exercises the banned-token rule with allocation-free hot code.
// CEP:STATUS: complete
// CEP:FAILURE: none
// CEP:ASSUMES: none
// CEP:COST: cold; fixture only.
// CEP:EVIDENCE: cep_lint --self-test.
fn sum_pairs(buf: &[u8]) -> u64 {
    let mut total = 0;
    let mut k = 0;
    while k < buf.len() {
        total += u64::from(buf[k]);
        k += 1;
    }
    total
}

